        ingredients: [{"type":"주성분","name":"피나스테리드 Finasteride","amount":"5mg","role":"5α-환원효소 2형 억제 → 전립선 DHT 감소 (전문의약품, 비뇨생식기관용약 분류)"}],
        content: "피나스테아정의 주성분은 피나스테리드 5mg이에요. 식약처 허가사항(품목번호 201601093)에 등록된 분류는 \"기타의 비뇨생식기관 및 항문용약\"으로, 모발용제(탈모용)가 아니에요. 1mg 탈모약(프로페시아·바로피나정·아스테리정 등)과 성분은 같지만 용량이 5배 높아요.\n\n작용 기전은 5α-환원효소 2형 억제예요. 테스토스테론의 DHT 전환을 막아 전립선 조직 DHT 농도를 낮추고, 비대된 전립선이 점차 축소돼요. 효과 판단까지 최소 6개월 이상 복용이 필요해요.\n\n에이치엘비제약(주)이 2016년 2월에 허가받았어요. 같은 5mg 라인 중 한국MSD 프로스카(오리지널)·바이넥스 프로스타트정·경동제약 유로스칸정·구주제약 피나그렌정 등이 있고, 모두 의약품동등성시험을 통과한 제네릭이라 약효는 동등해요. 차이는 제조사·시판 연도·부형제·도매 채널이에요. 9년 누적 시판으로 도매 단가가 안정된 라인이에요."
