        title: "피나스테아정 효과 — 양성 전립선비대증(BPH) 적응증, 탈모는 적응증 아님",
        content: "허가사항에 등록된 적응증은 양성전립샘비대증의 증상 개선·비후된 전립선의 퇴행·요류 개선·급성 요폐 발생빈도 감소·전립선 수술 필요성 감소예요. 모두 비뇨기 영역이고, 탈모 적응증은 등록되어 있지 않아요.\n\n작용 기전은 5α-환원효소 2형 억제로 전립선 DHT를 감소시키는 거예요. 비대된 전립선이 점차 축소되고, 요도 압박이 줄어 배뇨 증상이 개선돼요. 장기 복용 시 전립선 수술 필요성도 감소한다고 허가사항에 명시되어 있어요.\n\n신부전 환자(크레아티닌청소율 9.0 mL/min)·70세 이상 고령자도 별도 용량 조절이 필요 없어요. 5mg 용량은 탈모 임상이 설계되지 않았기 때문에 탈모에 대한 유효성·안전성이 입증되지 않았어요. 탈모용은 1mg 모발용제 라인을 따로 처방받으셔야 해요."
