        content: "허가사항 기준 용법은 \"피나스테리드로서 1일 1회 5mg을 식사와 관계없이 경구투여\"예요. 매일 같은 시간을 정해두면 좋아요. 코팅 정제를 그대로 통째로 삼키세요.\n\n신부전 환자(크레아티닌청소율 9.0 mL/min)·70세 이상 고령자도 별도 용량 조절이 필요 없어요. 복용 잊었을 때는 생각났을 때 1정만 복용하고, 다음 복용 시간이 가까우면 건너뛰세요. 한 번에 2정 복용은 금지예요.\n\n분할·분쇄는 허가사항에서 금지하고 있어요. 깨진 조각을 임산부가 만지면 남성 태아에게 영향을 줄 수 있어, 가정 내 보관도 임부와 분리해야 해요. 효과 평가까지 최소 6개월 복용이 필요해요."
