        content: "허가사항 \"투여하지 말 것\" 항목 첫 번째는 \"임부 또는 임신하고 있을 가능성이 있는 여성\"이에요. 5α-환원효소 억제제는 테스토스테론의 DHT 전환을 저해해 남성 태아 외부생식기 비정상을 초래할 수 있어요. 부서진 정제 조각도 만지면 안 돼요.\n\n두 번째 금기는 \"양성전립샘비대증 등으로 이 약 5mg 또는 다른 5α-환원효소 억제제를 복용하고 있는 환자\"예요. 두타스테리드(아보다트·머카나정 등)·5mg 피나스테리드와 동시 복용은 절대 금지예요. 간 기능 이상 환자는 신중히 투여해야 해요.\n\n허가사항 경고 항목에는 \"피나스테리드 1mg을 투여한 환자에서 우울한 기분, 우울증이 보고되었고, 이보다는 적은 건수로 자살생각을 포함한 기분변형이 보고\"되었다고 명시되어 있어요. 정신학적 증상이 생기면 즉시 복용 중단 + 의료 상담이 원칙이에요."
