    heroDescription: "피나드정을 탈모약으로 알고 검색하셨다면 한 가지 짚어드릴 게 있어요. 이 약은 사실 양성 전립선비대증 치료제(피나스테리드 5mg)예요. 식약처 허가사항(품목번호 201500591)에서 분류는 \"기타의 비뇨생식기관 및 항문용약\"이고 적응증은 비대된 전립선의 퇴행·요류 개선·급성 요폐 발생빈도 감소예요. 같은 5mg 라인 중 (주)이든파마가 2015년 2월에 허가받아 10년 누적 시판된 라인이에요. 이든파마는 1mg 탈모 라인(두타엠정 0.5mg)도 가진 회사예요.",
