        content: "에피나시정의 주성분은 피나스테리드 1mg이에요. 식약처 허가사항(품목번호 201405462)에 등록된 분류는 \"[02670] 모발용제(발모, 탈모, 염모, 양모제)\"로, 5mg(전립선비대증 치료제) 라인과는 분류 자체가 분리돼 있어요.\n\n작용 기전은 5α-환원효소 2형을 선택적으로 억제해, 테스토스테론이 디히드로테스토스테론(DHT)으로 전환되는 과정을 차단하는 거예요. 두피 모낭의 DHT 농도가 낮아지면 위축되던 모낭이 회복기에 접어들고, 모발이 다시 굵어져요.\n\n풍림무약(주)이 2014년 11월에 허가받았어요. 같은 1mg 모발용제 라인 중 11년 누적 시판된 안정 라인이고, 도매 채널이 일정 수준 안정된 편이에요. 메디페시아정(고려제약 2007, 18년) 다음 시기에 진입한 라인이에요."
