        content: "허가사항에 등록된 적응증은 \"성인남성(만 18~41세)의 남성형 탈모증(안드로겐 탈모증)의 치료\" 단일 항목이에요. 여성·소아·41세 초과·원형탈모·산후탈모는 모두 적응증 밖이에요. \"용량을 증량하면 유효성이 증대된다는 근거가 없다\"고도 명시돼 있어 임의로 늘려 복용해도 의미가 없어요.\n\n허가사항이 인용한 효과 판단 기준은 \"일반적으로 3개월 이상 복용해야 치료효과를 볼 수 있으며, 치료효과 유지를 위해 지속적으로 복용할 것을 권장\"이에요. 효과 평가는 보통 복용 6개월 시점 사진 비교로 진행해요. 초기 1~2개월에 일시적 탈락(쉐딩)이 보일 수 있는데, 휴지기 모발이 성장기 모발에 밀려 나오는 정상 반응이에요.\n\n중단 시 변화는 허가사항에 \"복용을 중단하면 12개월 내에 치료효과는 사라지게 된다\"고 명시돼 있어요."
