        content: "허가사항 기준 용법은 \"피나스테리드로서 1일 1회 1mg을 경구투여하며, 식사와 관계없이 투여\"예요. 매일 같은 시간을 정해두면 잊지 않아요. 정해진 1mg 단일 용량이 표준이라, 더 많이 먹는다고 효과가 좋아지지 않아요.\n\n복용 잊었을 때는 생각났을 때 1정만 먹고, 다음 복용 시간이 가까우면 건너뛰세요. 2정을 한꺼번에 먹는 건 권장되지 않아요. 코팅 정제이므로 부수거나 가루로 만들면 안 돼요. 부서진 조각을 임부가 만지면 남성 태아 외부생식기 비정상 위험이 있어요.\n\n효과는 짧게 보지 말고 최소 3개월, 가능하면 6개월 시점 사진으로 평가하세요. 정기 진료를 통한 평가가 권장돼요."
