        content: "두타케어정의 주성분은 두타스테리드(Dutasteride) 0.5mg이에요. 두타스테리드는 5알파환원효소 1형과 2형을 모두 억제하는 성분이에요. 피나스테리드가 2형만 억제하는 것과 달리, 두타스테리드는 1형까지 억제해서 DHT를 더 강력하게 차단해요.\n\n주식회사더유제약에서 제조한 두타케어정은 아보다트(Avodart)의 제네릭 의약품이에요. 정제 형태로, 부수거나 분쇄하지 않고 통째로 삼켜야 해요.\n\n두타스테리드는 혈중 DHT를 약 90% 이상 감소시켜요. 피나스테리드(약 70% 감소)보다 강력한 DHT 억제 효과가 있어요. 전립선비대증과 남성형 탈모 모두에 허가된 이중 적응증 약물이에요.",
