        content: "두타프렌정은 양성 전립선 비대증의 증상 개선, 급성 요저류 위험성 감소, 수술 필요성 감소에 효과가 있어요. 추가로 성인 남성(만 18~50세)의 남성형 탈모(안드로겐성 탈모) 치료에도 허가돼 있어요.\n\n전립선비대증 치료 효과는 6개월 이상 복용해야 판단할 수 있어요. 탈모 치료 효과는 3~6개월부터 나타나기 시작해요. 피나스테리드로 효과가 부족했던 분이 두타스테리드로 전환하면 추가 개선을 기대할 수 있어요.\n\n복용을 중단하면 전립선이 다시 커지고 탈모도 재진행돼요. 두타프렌정은 지속 복용이 필요한 약이에요. 전립선비대증과 탈모를 동시에 관리할 수 있다는 점이 피나스테리드 대비 장점이에요.",
