        content: "복합마이녹실액은 남성형 탈모증(안드로젠탈모증)의 치료에 사용해요. 두피 혈류를 개선해 모낭에 영양 공급을 늘리고, 위축된 모낭을 활성화시켜요.\n\n효과를 판단하려면 최소 4개월 이상 꾸준히 사용해야 해요. 초기 1~2개월에 오히려 머리카락이 더 빠지는 '초기 탈락' 현상이 나타날 수 있는데, 휴지기 모발이 빠지고 새 성장기 모발이 나오는 정상 과정이에요.\n\n사용을 중단하면 3~6개월 이내에 원래 탈모 상태로 돌아가요. 복합마이녹실액은 유전적 요인이 없는 탈모, 원형 탈모, 출산 관련 탈모에는 효과가 없어요. 정확한 탈모 유형 진단이 먼저예요.",
