        content: "씨엠피나정은 5mg 전립샘비대증 치료제 라인이라 1mg 탈모약과 단가를 직접 비교하기 어려워요. 5mg 라인 안에서 보면 2014년 허가 후 11년 시판된 라인이고, 같은 5mg 그룹 중 한국오가논 피나스정(1995, 30년)이나 하나제약 푸로케어정(2005, 20년)보다 시판 연혁이 짧은 그룹에 속해요.\n\n다른 5mg 라인과의 또 한 가지 차이는 부형제예요. 씨엠피나정은 대두유 등 지질성 부형제를 사용한 라인이라, 콩·땅콩 알레르기 환자에게는 처방 대상이 아니에요. 이 부형제 차이 때문에 같은 성분 다른 회사 라인으로 변경할 때 약사·의사 상담이 필요할 수 있어요.\n\n전립샘비대증은 만성질환이라 최소 6개월 이상 복용을 전제로 처방돼요. 보험 적용 여부에 따라 본인부담금이 달라지니 처방전 발급 후 가까운 약국 두세 곳에 단가를 문의하시면 합리적이에요. 탈모 목적이면 1mg 모발용제 라인을 따로 살펴보셔야 해요.",
