        content: "삼천당두타스테리드정의 권장 용량은 1일 1회 1캡슐(두타스테리드 0.5mg)이에요. 식사와 관계없이 복용할 수 있고, 매일 같은 시간에 복용하는 게 좋아요.\n\n캡슐 내용물에 노출되면 구강 인두점막을 자극할 수 있으니, 캡슐을 씹거나 쪼개지 말고 통째로 삼켜요. 신장애 환자나 고령자는 용량 조절이 필요 없어요. 다만 간장애 환자에 대한 자료가 부족해 권장 용량이 확립되지 않았어요.\n\n복용을 잊었다면 생각난 즉시 복용하되, 다음 복용 시간이 가까우면 건너뛰세요. 한 번에 2캡슐을 복용하면 안 돼요. 삼천당두타스테리드정은 삼천당제약(주)의 전문의약품이므로 처방에 따라 꾸준히 복용하세요.",
