        content: "유로다트연질캡슐은 여성에게 투여하면 안 돼요. 두타스테리드는 피부를 통해 흡수되므로, 임신했거나 임신 가능성이 있는 여성은 누출되는 캡슐과 접촉을 피해야 해요. 만약 접촉했다면 즉시 물과 비누로 씻으세요.\n\n18세 미만 소아에게도 투여하면 안 돼요. 이 약이나 다른 5알파환원효소 억제제에 과민증이 있는 환자도 복용 금지예요. 임신을 계획하고 있는 남성은 생식능에 미치는 영향을 의사와 상담해야 해요.\n\n유로다트연질캡슐 복용 중에는 헌혈을 하면 안 돼요. 두타스테리드는 반감기가 매우 길어서(약 5주) 복용 중단 후에도 최소 6개월은 헌혈을 피해야 해요. (주)씨티씨바이오의 유로다트연질캡슐은 전문의약품이므로 정기 진료가 필수예요.",
