        content: "마이녹실겔의 주성분은 미녹시딜(Minoxidil) 5%예요. 미녹시딜은 두피 혈관을 확장시켜 모낭으로 가는 혈류량을 늘리고, 위축된 모낭을 다시 활성화하는 성분이에요.\n\n현대약품(주)에서 제조한 마이녹실겔은 겔 제형이에요. 액제보다 흘러내리지 않아 도포가 편하고, 프로필렌글리콜을 사용하지 않아 두피 자극이 적은 편이에요.\n\n미녹시딜은 원래 고혈압 치료제로 개발됐지만, 다모증(털 과다 성장) 부작용이 발견되면서 외용 탈모 치료제로 재개발된 성분이에요. 겔 타입은 두피 자극이 민감한 분에게 적합해요.",
