        content: "인트로미녹시딜정은 두 가지 상황에서 사용해요. 첫째, 증후성 또는 표적기관 손상에 의한 고혈압이에요. 둘째, 이뇨제와 두 종류의 혈압약을 최대 용량으로 써도 반응하지 않는 불응성 고혈압이에요.\n\n강력한 혈관 확장 효과로 다른 혈압약에 반응하지 않는 환자에서도 혈압을 낮출 수 있어요. 다만 단독으로 사용하면 안 되고, 반드시 이뇨제와 교감신경차단제(베타차단제)를 병용해야 해요.\n\n일반적인 고혈압이나 탈모 치료 목적으로는 사용하지 않아요. 인트로미녹시딜정은 다른 혈압약으로 조절이 안 되는 심각한 고혈압에만 사용하는 최후 수단의 약이에요.",
