        content: "케라탑캡슐은 1일 1회 1캡슐(피나스테리드 1mg)을 식사와 관계없이 경구투여해요. 아침이든 저녁이든 매일 같은 시간에 복용하는 게 효과 유지에 중요해요.\n\n용량을 늘려도 효과가 증가한다는 근거는 없어요. 1일 1mg을 초과해서 복용하면 부작용 위험만 높아져요. 캡슐을 열거나 씹지 말고 물과 함께 삼켜요. 피나스테리드 가루가 임산부 피부에 흡수되면 남성 태아에 영향을 줄 수 있어요.\n\n복용을 잊었다면 생각난 즉시 복용하되, 다음 복용 시간이 가까우면 건너뛰고 1캡슐만 복용해요. 케라탑캡슐의 치료 효과는 3개월 이상 지속 복용해야 나타나며, 중단하면 12개월 내에 탈모가 다시 진행돼요.",
