        content: "모아탄캡슐 복용 후 위장관 불쾌감(위통, 구토)이 나타날 수 있어요. 식사와 함께 복용하면 대부분 완화돼요. 공복 복용은 피하는 게 좋아요.\n\n발한(땀이 많이 남), 빈맥(맥박이 빨라짐), 가려움, 두드러기, 두통, 어지러움, 홍조도 드물게 보고됐어요. 이런 증상이 나타나면 즉시 복용을 중단하고 의사와 상담하세요.\n\n두부 이외의 신체 부위(팔, 다리, 복부 등)에 발모 현상이 나타날 수 있어요. 이 증상이 생기면 모아탄캡슐 복용을 즉시 중단하세요. 3~4개월 사용 후에도 탈모나 모발 상태에 개선이 없다면 다른 치료법을 의사와 논의하세요.",
