        content: "모아탄캡슐은 습기와 빛을 피해 25도 이하에서 보관해요. 직사광선을 피하고 서늘한 곳에 두세요. 욕실처럼 습기가 많은 곳은 캡슐이 눅눅해질 수 있으니 피해요.\n\nPTP 포장(은박 포장)에서 미리 꺼내지 말고 복용 직전에 꺼내세요. 캡슐이 변색되었거나 내용물이 굳어진 경우 사용하지 마세요. 어린이 손에 닿지 않는 곳에 보관하세요.\n\n유통기한이 지난 모아탄캡슐은 약국의 폐의약품 수거함에 버려요. (주)팜젠사이언스에서 만든 모아탄캡슐은 캡슐 제형이므로 습기 관리가 특히 중요해요.",
