        content: "모싱싱캡슐의 주성분은 피나스테리드(Finasteride) 1mg이에요. 피나스테리드는 5알파환원효소 2형(5-alpha reductase type 2)을 선택적으로 억제하는 성분이에요. 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막아서 두피 모낭 위축을 방지해요.\n\n모싱싱캡슐은 프로페시아의 제네릭 의약품이에요. 캡슐 제형이라 정제와 달리 삼키기 편하고, 위장 자극이 적은 편이에요. 식약처 생동성 시험을 통과해 오리지널과 동등한 효능이 확인됐어요.\n\nDHT는 유전적으로 민감한 모낭을 축소시키는 주범이에요. 모싱싱캡슐 복용 시 혈중 DHT 농도를 약 65~70% 줄여서 위축된 모낭이 다시 굵은 모발을 만들기 시작해요. 캡슐을 뜯거나 씹지 말고 통째로 삼켜야 해요.",
