        content: "모싱싱캡슐은 여성에게 투여가 금지된 약이에요. 피나스테리드는 임신 중 남성 태아의 외부 생식기 발달에 영향을 줄 수 있어요. 캡슐이 손상되지 않았다면 정상 취급 시 내용물과 접촉되지 않아요.\n\n만 18세 미만이나 만 41세 초과 남성은 허가 범위를 벗어나요. 모싱싱캡슐 복용 중에는 헌혈을 하면 안 되고, 중단 후 최소 1개월이 지나야 헌혈이 가능해요. 간 기능 이상 환자는 체내 농도가 높아질 수 있으니 의사와 상담 후 복용하세요.\n\n모싱싱캡슐은 전문의약품이므로 반드시 의사 처방이 필요해요. 유전적 요인이 없는 탈모, 원형 탈모, 출산 관련 탈모에는 효과가 없어요. 정확한 탈모 유형 진단 없이 자가 복용하지 마세요.",
