        content: "마이시딜캡슐의 주성분은 약용효모, 시스틴, 케라틴, 판토텐산칼슘(비타민B5), 티아민질산염(비타민B1), 파라아미노안식향산이에요. 이 성분들이 모발과 손톱 성장에 필요한 핵심 영양소를 공급해요.\n\n약용효모는 비타민, 필수 아미노산, 미네랄, 효소를 풍부하게 함유해 모발 성장의 기본 영양을 제공해요. 시스틴은 케라틴을 구성하는 핵심 아미노산으로 모발 성장을 촉진하고, 케라틴은 모발의 약 90%를 차지하는 주요 단백질이에요.\n\n원광제약(주)의 마이시딜캡슐은 판토가(Pantogar)와 동일한 성분 조합의 제네릭이에요. 비타민B5는 새로운 모발 세포 형성에 필수적이고, 비타민B1은 에너지 대사를 지원해요. 이 성분들이 복합적으로 작용해 영양 결핍성 탈모와 손상 모발 회복에 도움을 줘요.",
